-- CUI // SP-CTI
-- Migration 210: Create showcase_apps table.
--
-- This table backs the slides source connector
-- (tools/slides/sources/child_apps.py) which SELECTs published showcase
-- applications generated by ICDEV™ for slide deck content.
-- The Internal Awareness Engine gap detector flagged showcase_apps as an
-- orphan_db_table finding — referenced by SELECT but absent from any
-- numbered migration.
--
-- showcase_apps — catalog of ICDEV-generated demo/showcase child applications.

-- ── SQLite ────────────────────────────────────────────────────────────────
-- @sqlite-only
CREATE TABLE IF NOT EXISTS showcase_apps (
    id          TEXT    PRIMARY KEY,
    name        TEXT    NOT NULL,
    category    TEXT    NOT NULL DEFAULT '',
    description TEXT    NOT NULL DEFAULT '',
    status      TEXT    NOT NULL DEFAULT 'draft'
                        CHECK(status IN ('draft', 'published', 'archived')),
    slug        TEXT,
    metadata    TEXT    NOT NULL DEFAULT '{}',
    created_at  TEXT    DEFAULT (datetime('now')),
    updated_at  TEXT    DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_showcase_apps_status     ON showcase_apps(status);
CREATE INDEX IF NOT EXISTS idx_showcase_apps_category   ON showcase_apps(category);
CREATE INDEX IF NOT EXISTS idx_showcase_apps_created_at ON showcase_apps(created_at);

-- ── PostgreSQL ────────────────────────────────────────────────────────────
-- @pg-only
CREATE TABLE IF NOT EXISTS showcase_apps (
    id          TEXT    PRIMARY KEY,
    name        TEXT    NOT NULL,
    category    TEXT    NOT NULL DEFAULT '',
    description TEXT    NOT NULL DEFAULT '',
    status      TEXT    NOT NULL DEFAULT 'draft'
                        CHECK(status IN ('draft', 'published', 'archived')),
    slug        TEXT,
    metadata    TEXT    NOT NULL DEFAULT '{}',
    created_at  TEXT    DEFAULT (now()::text),
    updated_at  TEXT    DEFAULT (now()::text)
);
CREATE INDEX IF NOT EXISTS idx_showcase_apps_status     ON showcase_apps(status);
CREATE INDEX IF NOT EXISTS idx_showcase_apps_category   ON showcase_apps(category);
CREATE INDEX IF NOT EXISTS idx_showcase_apps_created_at ON showcase_apps(created_at);

-- @all
